import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const p=JSON.parse('{"title":"好诗相伴01｜见情真：情到深处成文章","description":"","frontmatter":{},"headers":[],"relativePath":"如何读懂一首诗/好诗相伴01｜见情真：情到深处成文章.md","filePath":"如何读懂一首诗/好诗相伴01｜见情真：情到深处成文章.md","lastUpdated":1779819710000}'),n={name:"如何读懂一首诗/好诗相伴01｜见情真：情到深处成文章.md"};function r(E,e,o,c,g,b){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="好诗相伴01-见情真-情到深处成文章" tabindex="-1">好诗相伴01｜见情真：情到深处成文章 <a class="header-anchor" href="#好诗相伴01-见情真-情到深处成文章" aria-label="Permalink to &quot;好诗相伴01｜见情真：情到深处成文章&quot;">​</a></h1><p>好诗相伴，千金不换，你好，我是天博。</p><p>到目前为止，我们讲了22讲，提到了很多的诗词。这些诗词中也许有你非常喜欢的，想要把它记下来的，不过你可能没有去背诵的精力。所以我录制了这个叫做“好诗相伴”的栏目，我会只朗诵课程中提到的诗词。你可以反复聆听来记忆这些诗词。愿你好诗相伴，千金不换。</p><p>我今天录的是“见情真”这个话题下的诗。你应该还记得，我们这个话题一共三讲，讲了友情、爱情和亲情三个方面的诗。</p><p>在 <a href="https://time.geekbang.org/column/article/388767" target="_blank" rel="noreferrer">友情</a> 方面，我们主要讲了白居易的《梦微之》，在煮酒论诗中提到了他的《别元九后咏所怀》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/0fa61529ddd449452c57a681c6e7b125.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/0fa61529ddd449452c57a681c6e7b125.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/cc150c8204f560bebbe31d50434572yy.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/cc150c8204f560bebbe31d50434572yy.jpg" alt=""></a></p><p>在讲 <a href="https://time.geekbang.org/column/article/389802" target="_blank" rel="noreferrer">爱情</a> 的时候，我们主要讲了陆游的《沈园二首》，讲的过程中我们还讲了陆游和唐琬的两首《钗头凤》，还提到了陆游的《春游》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/faab3912f3d42c0f38020eed9c62b6cf.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/faab3912f3d42c0f38020eed9c62b6cf.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/139e5e3837bb4d9f0e36f3538aee4073.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/139e5e3837bb4d9f0e36f3538aee4073.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/4c0b5fa63041f8b6d6f2b89b4748013c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/4c0b5fa63041f8b6d6f2b89b4748013c.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/f239400334cc4794e3f683136af8880a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/f239400334cc4794e3f683136af8880a.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/53bf054d1f9bbc041a0c57fcf33efdef.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/53bf054d1f9bbc041a0c57fcf33efdef.jpg" alt=""></a></p><p>在讲 <a href="https://time.geekbang.org/column/article/389831" target="_blank" rel="noreferrer">亲情</a> 的时候，我们讲了苏轼的《狱中寄子由二首·其一》，还在煮酒论诗里聊到了他的《和子由渑池怀旧》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/bdd894ce3642ef2384359c4e6a4cec89.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/bdd894ce3642ef2384359c4e6a4cec89.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/758f2992b16f54c74d37ea9905cbfc37.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/408554/758f2992b16f54c74d37ea9905cbfc37.jpg" alt=""></a></p><p>好了，到这里，我们今天的好诗相伴就结束了。如果这里面有你喜欢的诗，欢迎你多听两遍，把它背下来，让它滋养你的灵魂。</p>',17)])])}const f=t(n,[["render",r]]);export{p as __pageData,f as default};
